18	
19	// The native kustomize gate (DEVDESK-771). Go never applies a proxy to the
20	// loopback, so offlineEnviron cannot stop a native kustomize that reads an
21	// overlay naming http://127.0.0.1:8080/x.yaml from sending a GET to a service of
22	// this machine. The overlay is therefore read first, and kustomize is started
23	// only when every reference in it, and in everything it pulls in, can only name
24	// a path of this repository.
25	//
26	// The gate is a closed whitelist, not a list of what to refuse: a reference is
27	// accepted when localRef says it can only be a local path, the YAML is read the
28	// closed way (no anchor, alias, merge key, explicit tag, duplicate key, key that
29	// is not ASCII, second document), every field of the kustomization is one the
30	// gate knows, and every plugin is a builtin one. What it cannot judge is refused
31	// as such: kustomize is not started either. The fields and the plugin kinds are
32	// the ones of kustomize v5.8.3 (api v0.21.3, types.Kustomization and the
33	// builtinhelpers factories).
34	
35	// gateKind is what the gate says about an overlay.
36	type gateKind int
37	
38	const (
39		// gateOK: every reference is local, kustomize may be started.
40		gateOK gateKind = iota
41		// gateRemote: a reference that is not a path of the repository.
42		gateRemote
43		// gateUnchecked: something the gate cannot judge, or cannot read.
44		gateUnchecked
45	)
46	
47	func (k gateKind) String() string {
48		switch k {
49		case gateOK:
50			return "ok"
51		case gateRemote:
52			return "remote"
53		case gateUnchecked:
54			return "unchecked"
55		}
56		return fmt.Sprintf("gateKind(%d)", int(k))
57	}
58	
59	// gateVerdict is the answer for one overlay. File is relative to the limit, with
60	// forward slashes; Field is the YAML path of the entry, with list indices
61	// (resources[1], patches[0].path); for an inline plugin configuration it is the
62	// field of the kustomization followed by the field of the plugin
63	// (transformers[0].path), for a plugin file the field inside that file. Ref is
64	// what localRef was given.
65	type gateVerdict struct {
66		Kind                     gateKind
67		File, Field, Ref, Reason string
68	}
69	
70	// gateLimits bound what the gate reads of a repository that is not trusted.
71	type gateLimits struct {
72		// Depth is the number of levels of overlay below the first; Visited the
73		// number of distinct kustomizations read.
74		Depth, Visited int
75		// FileBytes is the size of one file; TotalBytes of every file read for one
76		// overlay.
77		FileBytes, TotalBytes int64
78	}
79	
80	var defaultGateLimits = gateLimits{Depth: 16, Visited: 256, FileBytes: 4 << 20, TotalBytes: 32 << 20}
81	
82	// localRef reports whether ref can only name a path of this repository. It
83	// accepts a non-empty string without a control character, without ':' (a scheme,
84	// a port, a drive), '@' (an ssh user) or '?' (a query), that is neither absolute
85	// nor starts with a separator, and whose first segment is not github.com (which
86	// kustomize reads as a git repository even when such a folder exists). reason is
87	// "" when it is local, and says why not otherwise.
88	func localRef(ref string) (ok bool, reason string) {
89		switch {
90		case ref == "":
91			return false, "it is empty"
92		case strings.IndexFunc(ref, unicode.IsControl) >= 0:
93			return false, "it holds a control character"
94		case strings.ContainsAny(ref, ":@?"):
95			return false, "it holds a character that a URL, an address or a drive uses"
96		case strings.HasPrefix(ref, "/") || strings.HasPrefix(ref, `\`) || filepath.IsAbs(ref):
97			return false, "it is an absolute path"
98		}
99		if first, _, _ := strings.Cut(ref, "/"); strings.EqualFold(first, "github.com") {
100			return false, "kustomize reads a name that starts with github.com as a git repository"
101		}
102		return true, ""
103	}
104	
105	// ── Reading a file the closed way ────────────────────────────────────────────
106	
107	// readGateYAML reads one file of an overlay and returns the mapping at the top of
108	// its only document. A reason says why it cannot be judged, and the node is nil.
109	func readGateYAML(file string, maxBytes int64) (*yaml.Node, string) {
110		data, reason := readGateFile(file, maxBytes)
111		if reason != "" {
112			return nil, reason
113		}
114		return parseGateYAML(data)
115	}
116	
117	// readGateFile reads a regular file of at most maxBytes.
118	func readGateFile(file string, maxBytes int64) ([]byte, string) {
119		maxBytes = max(maxBytes, 0)
120		info, err := os.Stat(file)
121		if err != nil {
122			return nil, "it cannot be read (" + errReason(err) + ")"
123		}
124		if !info.Mode().IsRegular() {
125			return nil, "it is not a regular file"
126		}
127		tooBig := fmt.Sprintf("it is larger than %d bytes", maxBytes)
128		if info.Size() > maxBytes {
129			return nil, tooBig
130		}
131		f, err := os.Open(file) //nolint:gosec // a file of the repository being scanned, vetted above
132		if err != nil {
133			return nil, "it cannot be read (" + errReason(err) + ")"
134		}
135		defer func() { _ = f.Close() }()
136		// The size may have changed since the stat: one byte more says it did.
137		data, err := io.ReadAll(io.LimitReader(f, maxBytes+1))
138		if err != nil {
139			return nil, "it cannot be read (" + errReason(err) + ")"
140		}
141		if int64(len(data)) > maxBytes {
142			return nil, tooBig
143		}
144		return data, ""
145	}
146	
147	// errReason is err without the path an os error carries.
148	func errReason(err error) string {
149		var pathErr *fs.PathError
150		if errors.As(err, &pathErr) {
151			return pathErr.Err.Error()
152		}
153		return err.Error()
154	}
155	
156	// parseGateYAML returns the mapping at the top of the only document of data.
157	func parseGateYAML(data []byte) (*yaml.Node, string) {
158		dec := yaml.NewDecoder(bytes.NewReader(data))
159		var doc yaml.Node
160		if err := dec.Decode(&doc); err != nil {
161			if errors.Is(err, io.EOF) {
162				return nil, "it holds no YAML document"
163			}
164			return nil, "it is not valid YAML"
165		}
166		var next yaml.Node
167		if err := dec.Decode(&next); !errors.Is(err, io.EOF) {
168			return nil, "it holds more than one YAML document"
169		}
170		if doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 || doc.Content[0].Kind != yaml.MappingNode {
171			return nil, "its top level is not a mapping"
172		}
173		top := doc.Content[0]
174		if problem := nodeProblem(top); problem != "" {
175			return nil, "it holds " + problem
176		}
177		return top, ""
178	}
179	
180	// nodeProblem names what makes a node something the gate does not read: kustomize
181	// resolves anchors, aliases and merge keys, applies tags, matches field names
182	// without regard to case (and, for a non-ASCII letter, to Unicode folding) and
183	// keeps the last of two equal keys, so a reading that does not do the same is
184	// not a reading of what kustomize will do.
185	func nodeProblem(n *yaml.Node) string {
186		switch {
187		case n.Kind == yaml.AliasNode:
188			return "an alias"
189		case n.Anchor != "":
190			return "an anchor"
191		case n.Style&yaml.TaggedStyle != 0:
192			return "an explicit tag"
193		}
194		switch n.Kind {
195		case yaml.MappingNode:
196			seen := map[string]bool{}
197			for i := 0; i+1 < len(n.Content); i += 2 {
198				key := n.Content[i]
199				if problem := keyProblem(key, seen); problem != "" {
200					return problem
201				}
202				if problem := nodeProblem(n.Content[i+1]); problem != "" {
203					return problem
204				}
205			}
206		case yaml.SequenceNode:
207			for _, c := range n.Content {
208				if problem := nodeProblem(c); problem != "" {
209					return problem
210				}
211			}
212		}
213		return ""
214	}
215	
216	func keyProblem(key *yaml.Node, seen map[string]bool) string {
217		if problem := nodeProblem(key); problem != "" {
218			return problem
219		}
220		switch {
221		case key.Kind == yaml.ScalarNode && key.Value == "<<":
222			return "a merge key"
223		case key.Kind != yaml.ScalarNode || key.Tag != "!!str":
224			return "a key that is not a string"
225		}
226		for i := 0; i < len(key.Value); i++ {
227			if key.Value[i] >= 0x80 {
228				return "a key that is not ASCII"
229			}
230		}
231		folded := strings.ToLower(key.Value)
232		if seen[folded] {
233			return "a duplicate key"
234		}
235		seen[folded] = true
236		return ""
