370	// gate is one run of vetOverlay.
371	type gate struct {
372		ctx     context.Context //nolint:containedctx // one run of the gate, never stored
373		root    string          // the limit, absolute, symbolic links resolved
374		lim     gateLimits
375		visited map[string]bool // directories entered, by real path
376		count   int             // kustomizations read
377		read    int64           // bytes read
