380	// gateSite is where a value was read: file is the file it is in (relative to
381	// the limit), dir the directory its references are relative to (the one of the
382	// kustomization, also for a plugin file), depth how far below the first overlay.
383	type gateSite struct {
384		file  string
385		dir   string
386		depth int
387	}
388	
389	func (s gateSite) remote(field, ref, reason string) gateVerdict {
390		return gateVerdict{Kind: gateRemote, File: s.file, Field: field, Ref: ref, Reason: reason}
391	}
392	
393	func (s gateSite) unchecked(field, ref, reason string) gateVerdict {
394		return gateVerdict{Kind: gateUnchecked, File: s.file, Field: field, Ref: ref, Reason: reason}
395	}
