445	// dir judges the kustomization of one directory (a real path inside the limit)
446	// and, through it, everything it pulls in. A directory with none holds nothing
447	// to follow.
448	func (g *gate) dir(real string, depth int) gateVerdict {
449		if g.visited[real] {
450			return gateVerdict{}
451		}
452		g.visited[real] = true
453		where := gateSite{file: g.rel(real), dir: real, depth: depth}
454		switch {
455		case g.ctx.Err() != nil:
456			return where.unchecked("", "", "the check was cancelled")
457		case depth > g.lim.Depth:
458			return where.unchecked("", "", fmt.Sprintf("overlays are nested more than %d levels deep", g.lim.Depth))
459		}
460		file, v := g.kustomizationFile(real)
461		if file == "" {
462			return v
463		}
464		if g.count++; g.count > g.lim.Visited {
465			return where.unchecked("", "", fmt.Sprintf("more than %d kustomizations are pulled in", g.lim.Visited))
466		}
467		site := gateSite{file: g.rel(file), dir: real, depth: depth}
468		// The kustomization file may itself be a link: what is read is what it names.
469		if target, err := filepath.EvalSymlinks(file); err != nil || !within(g.root, target) {
470			return site.unchecked("", "", "the kustomization file leaves the repository through a symbolic link")
471		}
472		node, reason := g.readYAML(file)
473		if reason != "" {
474			return site.unchecked("", "", reason)
475		}
476		return g.applyMap(mapOf(kustomizationRules), node, "", site, true)
477	}
