542	func (g *gate) applyList(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
543		if n.Kind != yaml.SequenceNode {
544			return s.unchecked(field, "", "a value that is not a list")
545		}
546		for i, e := range n.Content {
547			if v := g.apply(*r.elem, e, fmt.Sprintf("%s[%d]", field, i), s); v.Kind != gateOK {
548				return v
549			}
550		}
551		return gateVerdict{}
552	}
