655	// reference judges one reference: it must be local, and below the limit once
656	// symbolic links are resolved. A directory is read in turn when follow says so.
657	func (g *gate) reference(ref string, follow bool, field string, s gateSite) gateVerdict {
658		real, found, v := g.resolve(ref, field, s)
659		if v.Kind != gateOK || !found || !follow {
660			return v
661		}
662		info, err := os.Stat(real)
663		switch {
664		case err != nil:
665			return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
666		case info.IsDir():
667			return g.dir(real, s.depth+1)
668		}
669		return gateVerdict{}
670	}
